#!/usr/bin/env node
// Token reports.
//   report.mjs           extract every pinned source (toolchain folder), merge, write knowledge/
//   report.mjs --check   re-merge the committed knowledge/tokens/<source>.json files and fail if any
//                        generated file is stale (no sources needed; used in CI)
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { merge, PLATFORMS, CROSS_CHECK, NOT_FOUND } from './merge.mjs';

const SOURCES = ['material-web', 'compose-material3', 'material_ui', 'material-components-android'];

const sortRecords = recs => recs.slice().sort((a, b) =>
  (a.id ?? '').localeCompare(b.id ?? '') || (a.mode ?? '').localeCompare(b.mode ?? '') || a.native.localeCompare(b.native) || a.line - b.line);
const jsonLines = items => `[\n${items.map(i => JSON.stringify(i)).join(',\n')}\n]\n`;

export function fmt(v) {
  if (v === NOT_FOUND) return NOT_FOUND;
  const k = Object.keys(v)[0];
  const x = v[k];
  switch (k) {
    case 'dp': case 'sp': case 'ms': return `${x}${k}`;
    case 'number': return String(x);
    case 'hex': return x;
    case 'ref': return `→ ${x}`;
    case 'easing': return `cubic-bezier(${x.join(', ')})`;
    case 'string': return `"${x}"`;
    case 'shape': return `shape(${x.family}; ${x.corners.join(', ')})`;
    default: return `unparsed: ${String(x).replace(/\|/g, '\\|')}`;
  }
}

function summaryOf(bySource, r) {
  const perSource = {};
  for (const s of Object.keys(bySource).sort()) {
    const recs = bySource[s];
    perSource[s] = {
      records: recs.length,
      mapped: recs.filter(x => x.id && !x.derived).length,
      unmapped: recs.filter(x => !x.id || x.derived).length,
      unparsed: recs.filter(x => x.value.unparsed !== undefined).length,
      deprecated: recs.filter(x => x.deprecated).length,
    };
  }
  const perKind = {};
  for (const m of r.merged) { const k = m.id.split('.')[1]; perKind[k] = (perKind[k] || 0) + 1; }
  const perPlatform = {};
  for (const [p, src] of Object.entries(PLATFORMS)) {
    perPlatform[p] = {
      source: src,
      notFoundEntries: r.notFound[p].length,
      notFoundTokens: r.notFound[p].reduce((a, e) => a + (e.count ?? 1), 0),
      conflicts: r.conflicts.filter(c => c.values.some(v => v.where === src)).length,
    };
  }
  return {
    perSource, perKind, perPlatform,
    totals: {
      tokenKeys: r.merged.length,
      conflicts: { repoVsRepo: r.conflicts.filter(c => c.kind === 'repo-vs-repo').length, siteVsRepo: r.conflicts.filter(c => c.kind === 'site-vs-repo').length },
      siteBackedOverrides: r.siteBackedOverrides.length,
      notFoundEntries: Object.values(r.notFound).reduce((a, l) => a + l.length, 0),
      deprecatedIds: r.deprecated.length, unparsed: r.unparsed.length, unmapped: r.unmapped.length,
    },
  };
}

function conflictsMd(r) {
  const repo = r.conflicts.filter(c => c.kind === 'repo-vs-repo');
  const site = r.conflicts.filter(c => c.kind === 'site-vs-repo');
  const out = ['# Token conflicts', '',
    'Generated by `tools/extract/tokens/report.mjs`. Do not edit by hand.', '',
    'Precedence: each platform keeps the value from its own repository; the cross-platform canonical value is',
    "material-web's; when the site and a repository disagree, the repository wins. References are followed",
    'inside their own source before comparing; a unitless number (Flutter) is compared by magnitude.', '',
    `## Repo vs repo (${repo.length})`, '', '| token | mode | values | differing pairs |', '|---|---|---|---|'];
  for (const c of repo) {
    out.push(`| ${c.id} | ${c.mode ?? ''} | ${c.values.map(v => `${v.where}: ${fmt(v.value)}`).join('; ')} | ${c.pairs.map(p => p.join(' ≠ ')).join('; ')} |`);
  }
  out.push('', `## Site vs repo (${site.length})`, '', '| token | page | site value | repo value (wins) | note |', '|---|---|---|---|---|');
  for (const c of site) {
    out.push(`| ${c.id} | ${c.values[0].where.slice(5)} | ${fmt(c.values[0].value)} | ${c.values[1].where}: ${fmt(c.values[1].value)} | ${c.note ?? ''}:${c.line ?? ''} |`);
  }
  const sb = r.siteBackedOverrides;
  out.push('', `## Site, Flutter and Compose agree against material-web (owner decision) (${sb.length})`, '',
    'Owner policy (2026-11-13): in these cases material-web does not win automatically; each one is listed for',
    'an owner decision in the phase report.', '',
    '| token | page | site | material-web | material_ui | compose-material3 | note |', '|---|---|---|---|---|---|---|');
  for (const s of sb) {
    out.push(`| ${s.id} | ${s.site.page} | ${fmt(s.site.value)} | ${fmt(s.web)} | ${fmt(s.flutter)} | ${fmt(s.compose)} | ${s.site.note ?? ''}:${s.site.line ?? ''} |`);
  }
  return out.join('\n') + '\n';
}

function notFoundMd(r, notesNotFound = []) {
  const out = ['# NOT FOUND', '',
    'Generated by `tools/extract/tokens/report.mjs`. Do not edit by hand.', '',
    "A token is NOT FOUND for a platform when another pinned source defines it and the platform's own source",
    'does not. Values are never guessed; Phase 3 applies the resolution ladder in spec §3 and records each use.',
    'Deprecated tokens and names we could not map to a token id are listed separately and are not counted.', ''];
  for (const [p, src] of Object.entries(PLATFORMS)) {
    out.push(`## ${p} (${src}): ${r.notFound[p].reduce((a, e) => a + (e.count ?? 1), 0)} tokens in ${r.notFound[p].length} entries`, '');
    let comp = null;
    for (const e of r.notFound[p]) {
      if (e.component !== comp) { comp = e.component; out.push(`### ${comp}`, ''); }
      out.push(`- ${e.id}${e.mode ? ` @${e.mode}` : ''}${e.count ? ` (${e.count} tokens)` : ''} (available in: ${e.availableIn.join(', ')})`);
    }
    out.push('');
  }
  out.push(`## Deprecated tokens (not counted): ${r.deprecated.length}`, '', r.deprecated.join(', ') || '(none)', '');
  out.push(`## Unparsed values: ${r.unparsed.length}`, '', '| source | token | native | raw | file:line |', '|---|---|---|---|---|');
  for (const x of r.unparsed) out.push(`| ${x.source} | ${x.id ?? ''} | ${x.native} | ${String(x.raw).replace(/\|/g, '\\|')} | ${x.file}:${x.line} |`);
  out.push('', `## Unmapped native names: ${r.unmapped.length}`, '', '| source | native | derived id | file:line |', '|---|---|---|---|');
  for (const x of r.unmapped) out.push(`| ${x.source} | ${x.native} | ${x.id ?? '(none)'} | ${x.file}:${x.line} |`);
  out.push('', `## NOT FOUND in notes: ${notesNotFound.length}`, '',
    'Statements the knowledge notes mark `[NOT FOUND]` (values or facts no source gives, e.g. the default color variant for M3 Expressive). Collected by `tools/extract/knowledge/lint.mjs`.', '',
    '| note:line | statement |', '|---|---|');
  for (const n of notesNotFound) out.push(`| ${n.note}:${n.line} | ${n.text.replace(/\|/g, '\\|')} |`);
  return out.join('\n') + '\n';
}

export function renderAll(bySource, mcu, siteValues = [], notesNotFound = []) {
  const sorted = Object.fromEntries(Object.keys(bySource).sort().map(s => [s, sortRecords(bySource[s])]));
  const r = merge(sorted, siteValues);
  const files = new Map();
  for (const s of Object.keys(sorted)) files.set(`tokens/${s}.json`, jsonLines(sorted[s]));
  files.set('tokens/color-system.json', JSON.stringify(mcu, null, 2) + '\n');
  files.set('tokens/merged.json', jsonLines(r.merged));
  files.set('tokens/summary.json', JSON.stringify(summaryOf(sorted, r), null, 2) + '\n');
  files.set('conflicts.md', conflictsMd(r));
  files.set('not-found.md', notFoundMd(r, notesNotFound));
  return files;
}

export async function writeAll(dir, files) {
  for (const [rel, text] of files) {
    await mkdir(dirname(join(dir, rel)), { recursive: true });
    await writeFile(join(dir, rel), text);
  }
}

export async function checkAll(dir, files) {
  const stale = [];
  for (const [rel, text] of files) {
    const cur = existsSync(join(dir, rel)) ? await readFile(join(dir, rel), 'utf8') : null;
    if (cur !== text) stale.push(rel);
  }
  return stale;
}

async function extractAll(root) {
  const { sourceDir } = await import('../sources/lock.mjs');
  const { extractWeb } = await import('./web.mjs');
  const { extractCompose } = await import('./compose.mjs');
  const { extractFlutter } = await import('./flutter.mjs');
  const { extractMdc } = await import('./mdc.mjs');
  const { extractMcu } = await import('./mcu.mjs');
  const aliases = JSON.parse(await readFile(join(root, 'tools', 'extract', 'tokens', 'aliases.json'), 'utf8'));
  const web = await extractWeb(join(sourceDir('material-web'), 'tokens', 'versions', 'latest', 'sass'));
  const knownIds = new Set(web.filter(r => !r.derived).map(r => r.id));
  const flutter = await extractFlutter(join(sourceDir('material_ui'), 'packages', 'material_ui', 'tool', 'gen_defaults', 'data'), { knownIds });
  for (const r of flutter) knownIds.add(r.id);
  return {
    bySource: {
      'material-web': web,
      material_ui: flutter,
      'compose-material3': await extractCompose(join(sourceDir('compose-material3'), 'commonMain', 'androidx', 'compose', 'material3', 'tokens'), { knownIds, aliases }),
      'material-components-android': await extractMdc(join(sourceDir('material-components-android'), 'lib', 'java', 'com', 'google', 'android', 'material'), { knownIds }),
    },
    mcu: await extractMcu(join(sourceDir('material-color-utilities'), 'package')),
  };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
  const kdir = join(root, 'knowledge');
  const siteFile = join(kdir, 'site-values.json');
  const siteValues = existsSync(siteFile) ? JSON.parse(await readFile(siteFile, 'utf8')) : [];
  const nfFile = join(kdir, 'notes-not-found.json');
  const notesNotFound = existsSync(nfFile) ? JSON.parse(await readFile(nfFile, 'utf8')) : [];
  try {
    if (process.argv.includes('--check')) {
      const bySource = {};
      for (const s of SOURCES) bySource[s] = JSON.parse(await readFile(join(kdir, 'tokens', `${s}.json`), 'utf8'));
      const mcu = JSON.parse(await readFile(join(kdir, 'tokens', 'color-system.json'), 'utf8'));
      const stale = await checkAll(kdir, renderAll(bySource, mcu, siteValues, notesNotFound));
      if (stale.length) {
        console.error(`token reports are stale: ${stale.join(', ')}; run \`npm run extract:tokens\``);
        process.exitCode = 1;
      } else console.log('token reports: up to date');
    } else {
      const { bySource, mcu } = await extractAll(root);
      const files = renderAll(bySource, mcu, siteValues, notesNotFound);
      await writeAll(kdir, files);
      console.log(files.get('tokens/summary.json'));
    }
  } catch (e) {
    console.error(e.stack || e.message);
    process.exitCode = 1;
  }
}

export { CROSS_CHECK };
